			WithServerUrl(server.URL).
			WithAuthToken(testToken)
		config.HTTPClient = server.Client()

		apiClient := client.NewAPIClient(config)
		apiClient.GetConfig().HTTPClient = server.Client()
		api := (*TagsAPIService)(&apiClient.Common)

		_, httpResponse, err := api.UpdateTag(id).Aid(aid).TagInfo(requestBody).Execute()
		if err == nil {
			t.Fatalf("UpdateTag() error = nil, want *GenericAPIError")
		}
